        raise ValueError(f"headcount for {team!r} must be positive, got {headcount}")

# Preserve the listed order so that both the result and the final
# tie-break ("team listed first") follow ``headcounts``.
allocation = {team: 0 for team in headcounts}
for _ in range(desks):
    # ``max`` returns the first maximal element, so listed order breaks
    # any remaining tie. Fractions keep quotient comparisons exact.
    best = max(
        allocation,
        key=lambda team: (
            Fraction(headcounts[team], allocation[team] + 1),
            headcounts[team],
        ),
    )
    allocation[best] += 1
return allocation
